draw:
var th = p.angle * Math.PI / 180;
var cone = Math.atan(p.mus);

var ox = 34, oy = H - 34;
var len = W - 80;
var tipY = oy - len * Math.tan(th);
if (tipY < 40) { len = (oy - 40) / Math.tan(th); tipY = 40; }

ctx.strokeStyle = C.rule; ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(ox, oy); ctx.lineTo(ox + len, oy); ctx.lineTo(ox + len, tipY); ctx.closePath();
ctx.stroke();

var cx = ox + len * 0.52;
var cy = oy - (len * 0.48) * Math.tan(th);

ctx.save();
ctx.translate(cx, cy);
ctx.rotate(-th);
ctx.fillStyle = C.figure; ctx.globalAlpha = 0.22;
ctx.fillRect(-20, -26, 40, 26);
ctx.globalAlpha = 1;
ctx.strokeStyle = C.ink; ctx.lineWidth = 1.5;
ctx.strokeRect(-20, -26, 40, 26);
ctx.restore();

var px = cx - Math.sin(th) * 13;
var py = cy - Math.cos(th) * 13;

function arrow(x1, y1, x2, y2, col, wid) {
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = wid || 2;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  var ang = Math.atan2(y2 - y1, x2 - x1);
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - 8 * Math.cos(ang - 0.4), y2 - 8 * Math.sin(ang - 0.4));
  ctx.lineTo(x2 - 8 * Math.cos(ang + 0.4), y2 - 8 * Math.sin(ang + 0.4));
  ctx.closePath(); ctx.fill();
}

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";

var L = 64;
arrow(px, py, px, py + L, C.ink);
ctx.fillStyle = C.ink;
ctx.fillText("mg", px + 6, py + L + 4);

var nx = Math.sin(th), ny = -Math.cos(th);
arrow(px, py, px + nx * L * Math.cos(th), py + ny * L * Math.cos(th), C.figure);
ctx.fillStyle = C.figure;
ctx.fillText("N = mg cos", px + nx * L * Math.cos(th) + 4, py + ny * L * Math.cos(th) - 4);

var tx = -Math.cos(th), ty = -Math.sin(th);
arrow(px, py, px - tx * L * Math.sin(th), py - ty * L * Math.sin(th), C.accent);
ctx.fillStyle = C.accent;
ctx.fillText("mg sin", px - tx * L * Math.sin(th) + 4, py - ty * L * Math.sin(th) + 14);

arrow(px, py, px + tx * L * Math.sin(th), py + ty * L * Math.sin(th), C.accent);
ctx.fillText("friction", px + tx * L * Math.sin(th) - 56, py + ty * L * Math.sin(th) - 6);

ctx.setLineDash([3, 4]);
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
var R = 78;
var base = Math.atan2(ny, nx);
ctx.beginPath();
ctx.moveTo(px, py);
ctx.lineTo(px + R * Math.cos(base - cone), py + R * Math.sin(base - cone));
ctx.stroke();
ctx.beginPath();
ctx.moveTo(px, py);
ctx.lineTo(px + R * Math.cos(base + cone), py + R * Math.sin(base + cone));
ctx.stroke();
ctx.beginPath();
ctx.arc(px, py, R, base - cone, base + cone);
ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("friction cone, half angle " + (cone * 180 / Math.PI).toFixed(1) + " deg", 10, 16);
ctx.fillText("slope " + p.angle.toFixed(0) + " deg", 10, 32);

out.note = (Math.tan(th) <= p.mus)
  ? "mg points inside the cone: the surface can hold it (tan = " + Math.tan(th).toFixed(3) + " <= " + p.mus.toFixed(2) + ")"
  : "mg points outside the cone: no way to hold it (tan = " + Math.tan(th).toFixed(3) + " > " + p.mus.toFixed(2) + ")";
